L4_1.m_Talk_KOREA = "날씨 맑음! 풍속 양호!"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "天気よし！　風速良好！　"
L4_1.m_Talk_ENG = "We got clear weather and good wind!"
