L5_1.m_bCharPinup = true
L5_1.m_Talk_KOREA = "마치 밤하늘의 달과 별도 오늘의 운명을 점지하고 있었던 것만 같은 최적의 날!"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "まるで夜空のお星様もお月様も、今日何が起きるかを知っていたかのような最高の決勝戦日和！"
L5_1.m_Talk_ENG = "It's as if the moon and stars have aligned to bless this perfect night's fate!"
L5_1.m_Talk_TWN = "連天公也作美，今天的天氣非常適合比賽呢！"
L5_1.m_Talk_THA = "ราวกับว่าดวงจันทร์และดวงดาวเรียงชิดกันเพื่ออวยพรชะตากรรมในค่ำคืนที่สมบูรณ์แบบนี้!"
L5_1.m_Talk_VTN = "Cứ như thể mặt trăng và các ngôi sao đã cùng phù hộ cho số phận của đêm hoàn hảo này!"
L5_1.m_Talk_SCN = "夜空的月亮和星星就好像也算到了今天的命运一般，天气非常适合比赛！"
L5_1.m_Talk_DEU = "Es ist, als hätten sich Mond und Sterne zusammengetan, um das Schicksal dieser perfekten Nacht zu segnen!"
L5_1.m_Talk_FRA = "C'est comme si la lune et les étoiles s'étaient alignées pour bénir le sort de cette nuit parfaite !"
