L8_1.m_Pos = "C"
L8_1.m_Crash = 15
L8_1.m_Talk_KOREA = "예─이! 시청자 여러분! 건의 요정 밋치미치야!"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "イェーイ！　視聴者のみなさん！　ガントレットの妖精、ミッチーミッチーだよ！"
L8_1.m_Talk_ENG = "EYYY! Hi, everyone! It's your Gauntlet fairy, Mitchie-Mitchie!"
L8_1.m_Talk_TWN = "耶—！各位觀眾！我是聖鎧精靈，米琪！"
L8_1.m_Talk_THA = "เฮ้! สวัสดีทุกคน! ฉันคือนางฟ้า ก๊อตเล็ท ของคุณ มิทชี่-มิทชี่!"
L8_1.m_Talk_VTN = "EYYY! Chào mọi người! Nàng tiên Gauntlet Mitchie-Mitchie của các bạn đây!"
L8_1.m_Talk_SCN = "耶——！各位观众！我是你们的圣铠精灵，米琪米琪！"
L8_1.m_Talk_DEU = "Hallihallo, an alle Zuschauer! Hier ist wieder eure Fehden-Fee, Mitchie-Mitchie!"
L8_1.m_Talk_FRA = "Hééé ! Salut tout le monde ! C'est votre fée de la Compétition, Mitchie Mitchie !"
L9_1 = {}
L9_1.m_CutScenKey_Talk = "CHARADE2_ACT4_STAGE1_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 5700403
L9_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "MITCH_NPC_NULL_NULL"
L9_1.m_Pos = "C"
L9_1.m_Crash = 30
L9_1.m_Talk_KOREA = "지금 이곳은 결승전 개막식이 펼쳐지고 있는 G 스타디움 현장─☆"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "今私は、決勝戦開幕式の行われているここ、Gスタジアムに来てるよ～☆"
L9_1.m_Talk_ENG = "I'm currently in G Stadium, where the finals are about to be held☆!"
L9_1.m_Talk_TWN = "這裡是舉行決賽開幕式的G體育場現場—☆"
L9_1.m_Talk_THA = "ตอนนี้ฉันอยู่ที่ สนามกีฬา G ซึ่งเป็นที่ที่รอบชิงชนะเลิศกำลังจะจัดขึ้น☆!"
L9_1.m_Talk_VTN = "Tôi hiện đang ở Sân vận động G, nơi mà trận chung kết sắp diễn ra☆!"
L9_1.m_Talk_SCN = "这里是举行决赛开幕式的G体育场现场——☆"
L9_1.m_Talk_DEU = "Ich befinde mich derzeit im G-Stadion, wo bald das Finale stattfinden wird ─☆"
L9_1.m_Talk_FRA = "Je me trouve actuellement dans le stade G, où la finale est sur le point de commencer !☆"
L10_1 = {}
