L13_1 = 0.15
L11_1[1] = L12_1
L11_1[2] = L13_1
L10_1.m_Bounce = L11_1
L10_1.m_Talk_KOREA = "이곳에서의 1분 1초가 건틀렛, 아니 샤레이드의 역사에 새겨지고 있는 중이라구─!"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "ここでの1分1秒がガントレット、いや、シャレードの歴史に刻まれている─！"
L10_1.m_Talk_ENG = "Every second and every minute in this place will go down in the history of Gauntlet, no, Charade!"
L10_1.m_Talk_TWN = "在這裡的一分一秒都將寫入聖鎧，不，是查雷德的歷史裡—！"
L10_1.m_Talk_THA = "ทุกวินาทีและทุกนาทีในสถานที่นี้จะลงไปในประวัติศาสตร์ของ ก๊อตเล็ท  ไม่สิ ชาเรด!"
L10_1.m_Talk_VTN = "Từng giây từng phút ở nơi này sẽ đi vào lịch sử của Gauntlet, không, Charade!"
L10_1.m_Talk_SCN = "在这里的一分一秒都将写入圣铠，哦不，查雷德的历史中——！"
L10_1.m_Talk_DEU = "Jede Sekunde und jede Minute an diesem Ort wird in die Geschichte der Fehde eingehen, nein, in Charades ─!"
L10_1.m_Talk_FRA = "Chaque minute et chaque seconde passée ici entrera dans les annales de la Compétition, non, de Charade !"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "CHARADE2_ACT4_STAGE1_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5700403
L11_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_LAUGH"
L11_1.m_CharStrID = "MITCH_NPC_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Crash = 10
L11_1.m_Talk_KOREA = "그런 현장에 있을 수 있다니─! 미치의 가슴 두근거리기 시작했어─!"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "そんな現場にいられるなんて～！　ミッチー、ワクワクしてきちゃった─！"
L11_1.m_Talk_ENG = "I can't believe I'm here right now! My heart's pounding like a drum!"
L11_1.m_Talk_TWN = "我有幸親臨現場—！米琪的心正砰砰跳呢—！"
L11_1.m_Talk_THA = "ฉันไม่อยากจะเชื่อเลยว่าฉันอยู่ที่นี่ตอนนี้! หัวใจฉันเต้นแรงเหมือนกลอง!"
L11_1.m_Talk_VTN = "Tôi không thể tin được là tôi đang ở đây lúc này! Tim tôi đập nhanh như nhịp trống dồn vậy!"
L11_1.m_Talk_SCN = "能够幸亲临现场——！米琪的心正剧烈地跳动呢——！"
L11_1.m_Talk_DEU = "Ich kann nicht glauben, dass ich gerade hier bin ─! Mein Herz klopft wie verrückt ─!"
L11_1.m_Talk_FRA = "Je n'arrive pas à croire que je suis ici en ce moment même ! Mon cœur bat à la chamade !"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "CHARADE2_ACT4_STAGE1_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5700403
L12_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "MITCH_NPC_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Crash = 10
L12_1.m_Talk_KOREA = "이 뜨거운 현장의 분위기! 액정 너머의 시청자분들도 느껴지려나?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "この現場の熱い雰囲気！　液晶越しのみんなにも伝わってるかな？"
L12_1.m_Talk_ENG = "I can feel the passion and excitement! I wonder if you all can feel it through your screens too!"
L12_1.m_Talk_TWN = "現場的氣氛好火熱！在螢幕後方的觀眾也能感受到嗎？"
L12_1.m_Talk_THA = "ฉันสัมผัสได้ถึงความหลงใหลและความตื่นเต้น! ฉันสงสัยว่า\nพวกคุณทุกคนสามารถสัมผัสมันผ่านหน้าจอของคุณเหมือนกันหรือเปล่า!"
L12_1.m_Talk_VTN = "Tôi có thể cảm nhận được niềm đam mê và cả sự phấn khích! Không biết tất cả các bạn có thể cảm nhận được điều đó qua màn hình của mình không!"
L12_1.m_Talk_SCN = "这火热的现场氛围！屏幕后方的观众朋友们也能感受到吗？"
L12_1.m_Talk_DEU = "Die Stimmung im Stadion ist aufgeheizt! Ich frage mich, ob ihr es alle auch durch eure Bildschirme spüren könnt?!"
L12_1.m_Talk_FRA = "Cette ambiance électrisante ! Je me demande si vous pouvez tous la ressentir derrière vos écrans !"
