L15_1.m_Crash = 15
L15_1.m_Talk_KOREA = "아! 때마침 스테이지에 등장하는 오늘의 챔피언─!"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "あ！　ちょうどステージに登場した本日のチャンピオン─！"
L15_1.m_Talk_ENG = "Oh! The champion just appeared on the stage!"
L15_1.m_Talk_TWN = "喔！說時遲那時快，我們的冠軍已經站上舞台—！"
L15_1.m_Talk_THA = "โอ้! แชมป์เพิ่งปรากฏตัวบนเวที!"
L15_1.m_Talk_VTN = "Ồ! Nhà vô địch vừa xuất hiện trên sân khấu!"
L15_1.m_Talk_SCN = "啊！今天的冠军在舞台登场了——！"
L15_1.m_Talk_DEU = "Oh! Der Champion ist gerade auf der Bühne erschienen ─!"
L15_1.m_Talk_FRA = "Oh ! La championne a fait son apparition sur la scène !"
