L16_1.m_Talk_KOREA = "리그의 정상에서 군림하고 있는 붉은 사자! 여제의 신화는 계속해서 이어진다─!"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "リーグの頂点に君臨する、赤い獅子！　女帝の神話はまだまだ続く─！"
L16_1.m_Talk_ENG = "The crimson lion that reigns from the top of the league! The legend of the empress will continue–!"
L16_1.m_Talk_TWN = "在聯賽巔峰上傲視群雄的紅獅！女帝的神話將繼續下去—！"
L16_1.m_Talk_THA = "สิงโตแดงที่ครองราชย์จากลีกสูงสุด! ตำนานจักรพรรดินีจะดำเนินต่อไป–!"
L16_1.m_Talk_VTN = "Con sư tử đỏ thẫm thống trị từ đỉnh cao của giải đấu! Truyền thuyết về nữ hoàng sẽ tiếp tục–!"
L16_1.m_Talk_SCN = "凌驾于联赛之巅的红狮！女帝的神话将继续延续——！"
L16_1.m_Talk_DEU = "Die purpurrote Löwin, die an der Spitze der Liga regiert! Die Legende der Kaiserin wird weitergehen ─!"
L16_1.m_Talk_FRA = "La lionne écarlate qui règne en maître dans la Compétition ! Le mythe de l'impératrice continue !"
