L17_1.m_Talk_KOREA = "전승무패의 관리국 공인 S급 카운터! 오지만디아스─!"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "全勝無敗。管理局公認のSランクカウンター！　オジマンディアス～！"
L17_1.m_Talk_ENG = "The undefeated, Administration confirmed Grade S Counter! OZYMANDIAS–!"
L17_1.m_Talk_TWN = "百戰百勝，管理局公認的S級制裁者！奧茲曼迪亞斯—！"
L17_1.m_Talk_THA = "ฝ่ายบริหารไร้พ่าย ยืนยัน เคาน์เตอร์เกรด S! โอซีแมนเดียส–!"
L17_1.m_Talk_VTN = "Counter cấp S bất bại được Cục Quản Lý xác nhận! OZYMANDIAS–!"
L17_1.m_Talk_SCN = "从无败绩的管理局公认S级制裁者！奥兹曼迪亚斯——！"
L17_1.m_Talk_DEU = "Der ungeschlagene, von der Administration als Klasse-S eingestufte Counter! Ozymandias ─!"
L17_1.m_Talk_FRA = "La Counter gradée S par l'Administration et invaincue à ce jour ! Ozymandias !"
