L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 5700403
L21_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L21_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L21_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "다들 내 경기를 보러 와 줘서 고마운걸."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "みんな、今日は私の試合を見に来てくれてありがとう。"
L21_1.m_Talk_ENG = "Thanks for coming to see my game, everyone!"
L21_1.m_Talk_TWN = "很感謝大家來看我的比賽。"
L21_1.m_Talk_THA = "ขอบคุณที่มาดูเกมของฉันนะทุกคน!"
L21_1.m_Talk_VTN = "Cảm ơn mọi người đã đến xem trận đấu của tôi!"
L21_1.m_Talk_SCN = "很感谢能来看我的比赛，大家！"
L21_1.m_Talk_DEU = "Vielen Dank, dass ihr alle vorbeigekommen seid, um euch mein Spiel anzusehen!"
L21_1.m_Talk_FRA = "Merci d'être venus voir mon match, tout le monde !"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "CHARADE2_ACT4_STAGE1_START@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 5700403
L22_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_LAUGH"
L22_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "하지만 미리 사과해야겠는데. 오늘 경기는 너무 빨리 끝날 것 같거든."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "でも先に謝っておくわ。今日の試合、一瞬で終わってしまうからね。"
L22_1.m_Talk_ENG = "But I think I'll have to apologize first. Because I feel that tonight's match is going to end pretty quickly."
L22_1.m_Talk_TWN = "但我必須提前跟大家說聲抱歉，因為今天的比賽很快就會結束。"
L22_1.m_Talk_THA = "แต่ฉันคิดว่าฉันต้องขอโทษก่อน เพราะรู้สึกว่าแมตช์คืนนี้จะจบเร็วมาก"
L22_1.m_Talk_VTN = "Nhưng tôi nghĩ tôi sẽ phải xin lỗi trước. Vì cảm giác trận đấu tối nay sẽ kết thúc khá nhanh đấy."
L22_1.m_Talk_SCN = "但我得提前和你们说句抱歉了，因为今天的比赛会结束得很快！"
L22_1.m_Talk_DEU = "Aber ich denke, ich muss mich schon mal im Voraus entschuldigen. Weil ich das Gefühl habe, dass das Spiel heute Abend ziemlich schnell vorbei sein wird."
L22_1.m_Talk_FRA = "Mais je crois que je vous dois des excuses. Car le match de ce soir risque de se terminer assez rapidement."
L23_1 = {}
L23_1.m_CutScenKey_SubTitle = "CHARADE2_ACT4_STAGE1_START@23#SubTitle"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 5700403
L23_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_fTitleTalkTime = 0
L23_1.m_SubTitle_KOREA = "<color=#ffd34c>■■ ■■</color> 챔피언 등장!! 오늘도 여왕님께 전재산 걸었다구!!\n<color=#ffd34c>■ ■</color> 너무 빨리 끝나도 실망하지 말래 ㅋㅋ 여유로운 거 봐라 ㅋㅋ\n<color=#ffd34c>■■■</color> 아니 ㅋㅋㅋ 오지만디아스를 어떻게 이기냐고 ㅋㅋㅋ\n<color=#ffd34c>■■ ■■</color> 카나리아는 좋겠네~ 여왕님한테 밟힐 수 있어서~\n<color=#ffd34c>■■ ■</color> 나도 밟히고 싶다 ㅋㅋㅋㅋㅋㅋㅋㅋ\n<color=#ffd34c>■■</color> 저 뒤에 검은 슈트는 누구지? 처음보는 백업 요원인데?"
L23_1.m_fSubTitleTalkTime = 0
L23_1.m_SubTitle_JPN = "<color=#ffd34c>■■ ■■</color> チャンピオン登場！！　今日も女王様に全財産賭けときました！！\n<color=#ffd34c>■ ■</color> 試合がすぐに終わってもがっかりしないでってこと？　余裕すぎるだろｗｗ\n<color=#ffd34c>■■■</color> さすがにオジマンディアスには勝てる絵が浮かばんなｗｗｗ\n<color=#ffd34c>■■ ■■</color> カナリアが羨ましいぜ～女王様に踏んでもらえて～ｗｗ\n<color=#ffd34c>■■ ■</color> 俺も踏んでほしいｗｗｗｗ\n<color=#ffd34c>■■</color> 後ろにいる黒いスーツって誰？　初めて見るバックアップメンバーだぞ？"
L23_1.m_SubTitle_ENG = "<color=#ffd34c>■■ ■■</color> The champion's here!! I bet my entire life's saving on you, my queen!!\n<color=#ffd34c>■ ■</color> She's asking us to not be disappointed if the game ends too quickly. LOL! Now that's confidence. HAHA!\n<color=#ffd34c>■■■</color> But, for real. LMAO! How can anyone beat Ozymandias? LOL!\n<color=#ffd34c>■■ ■■</color> I envy Canary Squad... They get to be stomped by the champion!\n<color=#ffd34c>■■ ■</color> I wish she would stomp on me too. LOLOLOL!\n<color=#ffd34c>■■</color> Who's that in the black suit behind her? Never seen that backup agent before?"
L23_1.m_SubTitle_TWN = "<color=#ffd34c>■■ ■■</color> 冠軍出場！！我今天也把所有身家都壓在女王身上囉！！\n<color=#ffd34c>■ ■</color> 還說比賽太快結束也別失望，呵呵～真是游刃有餘，呵呵\n<color=#ffd34c>■■■</color> 拜託，怎麼可能打得贏奧茲曼迪亞斯啦，呵呵呵呵\n<color=#ffd34c>■■ ■■</color> 真羨慕金絲雀～可以被女王踩在腳下～\n<color=#ffd34c>■■ ■</color> 我也想被踩，呵呵呵呵\n<color=#ffd34c>■■</color> 後面那個穿黑色西裝的是誰？第一次看到欸？是候補嗎？"
L23_1.m_SubTitle_THA = "<color=#ffd34c>■■ ■■</color> แชมป์มาแล้ว!! ฉันเดิมพันทั้งชีวิตของฉันไว้กับเธอ ราชินีของฉัน!!\n<color=#ffd34c>■ ■</color> เธอขอให้เราไม่ผิดหวังหากเกมจบลงเร็วเกินไป ฮ่าๆ! ตอนนี้นั่นคือความมั่นใจ ฮ่าฮ่า!\n<color=#ffd34c>■■■</color> แต่จริงๆ แล้ว ฮ่าๆ! ใครจะเอาชนะ โอซีแมนเดียสได้อย่างไร? ฮ่าๆ!\n<color=#ffd34c>■■ ■■</color> ฉันอิจฉาหน่วยแคนารี... พวกเขาโดนแชมป์กระทืบ!\n<color=#ffd34c>■■ ■</color> ฉัน หวังว่าเธอจะกระทืบฉันเหมือนกัน ฮ่าๆ!\n<color=#ffd34c>■■</color> นั่นใครในชุดสูทสีดำข้างหลังเธอ? ไม่เคยเห็นตัวแทนสำรองนั้นมาก่อนเหรอ?"
L23_1.m_SubTitle_VTN = "<color=#ffd34c>■■ ■■</color> Nhà vô địch đã đến rồi!! Tôi đã cược tiền tiết kiệm cả đời cho cô đấy, nữ hoàng của tôi!!\n<color=#ffd34c>■ ■</color> Cô ấy đang bảo chúng ta đừng thất vọng nếu kết thúc quá nhanh kìa. LOL! Quá tự tin. HAHA!\n<color=#ffd34c>■■■</color> Nhưng thực tế là vậy. HAHAA! Làm sao ai có thể đánh bại được Ozymandias? LOL!\n<color=#ffd34c>■■ ■■</color> Tôi ghen tị với Tiểu Đội Canary... Họ được nhà vô địch giẫm nát!\n<color=#ffd34c>■■ ■</color> Tôi ước gì cô ấy cũng giẫm lên tôi. LOLOLOL!\n<color=#ffd34c>■■</color> Ai mặc bộ đồ đen phía sau cô ấy vậy? Chưa bao giờ nhìn thấy người dự phòng đó cả?"
L23_1.m_SubTitle_SCN = "<color=#ffd34c>■■ ■■</color>冠军登场了！！我今天也把全部的财产押给女王大人了！！\n<color=#ffd34c>■ ■</color>结束得太快了也不要很失望，哈哈哈，真是很从容啊，噗哈哈\n<color=#ffd34c>■■■</color>我说，很难赢得了奥兹曼迪亚斯吧，哈哈哈\n<color=#ffd34c>■■ ■■</color>好羡慕金丝雀啊~可以被女王大人践踏呢~\n<color=#ffd34c>■■ ■</color>我也想被踩，姐姐踩我快踩我\n<color=#ffd34c>■■</color>后面的黑西装是谁？好像是第一次见的候补选手？"
L23_1.m_SubTitle_DEU = "<color=#ffd34c>■■ ■■</color> Der Champion ist da!! Ich habe heute mein gesamtes Vermögen auf dich gesetzt, meine Königin!!\n<color=#ffd34c>■ ■</color> Sie bittet uns darum, nicht allzu enttäuscht zu sein, weil das Spiel wahrscheinlich recht schnell vorbei sein wird. LOL.\n<color=#ffd34c>■■■</color> Aber wie wollen sie denn Ozymandias schlagen?\n<color=#ffd34c>■■ ■■</color> Ich beneide den Canary Trupp ... Sie werden von Ozymandias höchstpersönlich zertrampelt!\n<color=#ffd34c>■■ ■</color> Ich will auch von ihr zertrampelt werden!\n<color=#ffd34c>■■</color> Was sind das für Typen in schwarzen Anzügen hinter ihr? Diese Verstärkung sehe ich zum ersten Mal."
L23_1.m_SubTitle_FRA = "<color=#ffd34c>■■ ■■</color> La championne est là !! J'ai misé tout mon argent sur elle !!\n<color=#ffd34c>■ ■</color> Elle veut pas qu'on soit déçu si le match se termine rapidement lol on dirait qu'elle est sûre d'elle\n<color=#ffd34c>■■■</color> Non mais, qui pourrait bien battre Ozymandias ? mdr\n<color=#ffd34c>■■ ■■</color> Ils ont trop de chance les Canaris de pouvoir se faire marcher dessus par la reine !\n<color=#ffd34c>■■ ■</color> J'aimerais bien qu'elle me marche dessus moi aussi xD\n<color=#ffd34c>■■</color> C'est qui les types en armure noire derrière ? Je les ai jamais vus avant !"
