L27_1.m_Talk_KOREA = "챔피언과 맞은편 스테이지에 오르는 챌린저─!"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "チャンピオンの反対側からステージに登場するのはチャレンジャーの─！"
L27_1.m_Talk_ENG = "And on the other side, tonight's challenger climbs up to the stage–!"
L27_1.m_Talk_TWN = "而在冠軍對面的舞台，出場的是挑戰者—！"
L28_1 = "และอีกด้านหนึ่ง ผู้ท้าชิงคืนนี้ก็ปีนขึ้นไปบนเวที–!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Và ở phía bên kia, đội thách đấu tối nay bước lên sân khấu–!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "对面舞台登场的是冠军的挑战者——！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Und auf der anderen Seite betreten die heutigen Herausforderer die Bühne ─!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Et de l'autre côté, l'équipe adverse monte également sur scène !"
L27_1.m_Talk_FRA = L28_1
