L28_1.m_Crash = 15
L29_1 = "기어코, 삼등 시민들이 사고를 치고 말았다구─!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ついに、3等市民たちが常識を破った─！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "They did it! Those third-grade citizens have stirred up a ruckus–!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "三等市民大鬧聖鎧—！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "พวกเขาทำมัน! พลเมืองเกรด3 เหล่านั้นก่อความวุ่นวาย–!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Họ đã làm được! Những công dân hạng ba đó đã tạo nên một chấn động–!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "无法无天的三等市民——！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Sie haben es geschafft! Diese Bürger dritter Klasse haben für ordentlich Aufruhr gesorgt ─!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ils y sont arrivés ! Ces citoyens de troisième zone ont vraiment tout chamboulé !"
L28_1.m_Talk_FRA = L29_1
