L29_1.m_Crash = 30
L30_1 = "올해 첫 출전이라는 타이틀이 무색할 정도로, 바닥에서 결승까지 단번에 날아올랐다!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "今回初出場であるにも関わらず、一気に決勝まで上り詰めた！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "They are on an unbelievable run in their first ever Gauntlet! They made it all the way here from the bottom!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "雖然是今年首次參賽，卻一口氣從初賽晉級到決賽！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "พวกเขากำลังวิ่งอย่างเหลือเชื่อใน ก๊อตเล็ท ครั้งแรก! พวกเขามาอยู่ที่นี่จากด้านล่าง!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Họ đang có một cuộc chạy đua khó tin trong giải Gauntlet đầu tiên của mình! Họ đã đi đến đây từ dưới đáy!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "明明是今年首次参加比赛，但却从最底端一下飞到了决赛！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Sie sind zum allerersten bei der diesjährigen Fehde dabei und haben es von ganz unten bis hierher geschafft!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ils ont gravi les échelons depuis tout en bas alors qu'il s'agit de leur première participation à la Compétition !"
L29_1.m_Talk_FRA = L30_1
