L31_1 = "과연 해로운 새는 붉은 사자를 떨어트릴 수 있을 것인가!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "果たして、有害な鳥は赤い獅子を倒せるでしょうか！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Will those pesky birds be able to take down the mighty red lion?!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "究竟有害之鳥是否能戰勝紅獅呢！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "นกที่น่ารำคาญเหล่านั้นจะสามารถโค่นสิงโตแดงผู้ยิ่งใหญ่ได้หรือไม่!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Liệu những con chim phiền phức đó có thể hạ gục được con sư tử đỏ hùng mạnh không?!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "害群之鸟是否能战胜伟大的红狮呢！"
L30_1.m_Talk_SCN = L31_1
