L37_1 = "<color=#ffd34c>■■■■</color> 카나리아!! 역배 가즈아아아아아─!!\n<color=#ffd34c>■■ ■</color> 뭐야, 왜 아무 말도 안 해? 쫄았냐 ㅋㅋㅋㅋㅋㅋ\n<color=#ffd34c>■■</color> 근데 떨릴 만도 하지ㅋㅋㅋㅋ 나라도 진짜 쫄릴 듯 ㅋㅋㅋㅋ"
L36_1.m_SubTitle_KOREA = L37_1
L36_1.m_fSubTitleTalkTime = 0
L37_1 = "<color=#ffd34c>■■■■</color> カナリアにベッティングしたから、思いっきり稼がせてくれよ！！\n<color=#ffd34c>■■ ■</color> なんか無言じゃね？　ビビっているのかなｗｗｗｗ\n<color=#ffd34c>■■</color> 緊張すんのも無理はないわなｗｗｗ自分があの立場だったらまじ緊張すると思うｗｗ"
L36_1.m_SubTitle_JPN = L37_1
L37_1 = "<color=#ffd34c>■■■■</color> Let's go Canary! My bet's on you!!\n<color=#ffd34c>■■ ■</color> Huh? Why aren't they saying anything? Too scared to talk now? LOL!\n<color=#ffd34c>■■</color> I bet they're trembling like crazy up there. LMAO! I'd be too! LOL!"
L36_1.m_SubTitle_ENG = L37_1
L37_1 = "<color=#ffd34c>■■■■</color> 金絲雀！！我的金雞母─！！\n<color=#ffd34c>■■ ■</color> 怎麼不說話？害怕嗎？呵呵呵呵\n<color=#ffd34c>■■</color> 害怕也是正常的吧？呵呵呵～要是我也會怕，呵呵呵"
L36_1.m_SubTitle_TWN = L37_1
L37_1 = "<color=#ffd34c>■■■■</color> ไปคานารี่กันเถอะ! ฉันเดิมพันกับคุณ!!\n<color=#ffd34c>■■ ■</color> หือ? ทำไมพวกเขาไม่พูดอะไรเลย? กลัวเกินกว่าจะพูดตอนนี้เหรอ? ฮ่าๆ!\n<color=#ffd34c>■■</color> เดาได้เลยว่าข้างบนนั้นสั่นจนแทบบ้า ฮ่าๆ! ฉันก็เหมือนกัน! ฮ่าๆ!"
L36_1.m_SubTitle_THA = L37_1
L37_1 = "<color=#ffd34c>■■■■</color> Đi nào Canary! Tôi đặt cược vào các bạn!!\n<color=#ffd34c>■■ ■</color> Hả? Tại sao họ không nói gì cả? Quá sợ hãi đến nỗi không thể mở miệng sao? LOL!\n<color=#ffd34c>■■</color> Tôi cá là họ đang run rẩy như điên ở trên đó. LOL! Tôi cũng vậy! LOL!"
L36_1.m_SubTitle_VTN = L37_1
L37_1 = "<color=#ffd34c>■■■■</color>金丝雀！！给我反败为胜啊，我可是押了你们_!!\n<color=#ffd34c>■■ ■</color>什么啊，怎么没人说话？怂了？哈哈哈哈哈哈\n<color=#ffd34c>■■</color>不过确实会紧张吧，换做是我应该也很怂，哈哈哈哈"
L36_1.m_SubTitle_SCN = L37_1
L37_1 = "<color=#ffd34c>■■■■</color> Canary Trupp!! Ihr könnt es schaffen ─!!\n<color=#ffd34c>■■ ■</color> Was ist los? Warum sagen sie denn nichts? Haben sie Angst?\n<color=#ffd34c>■■</color> Bestimmt zittern ihnen die Knie vor Angst! LOL!"
L36_1.m_SubTitle_DEU = L37_1
L37_1 = "<color=#ffd34c>■■■■</color> Allez les canaris !!!\n<color=#ffd34c>■■ ■</color> Ben pourquoi ils disent rien ? Ils ont la frousse ou quoi ? lol\n<color=#ffd34c>■■</color> En même temps y'a de quoi ! Si c'était moi je me ferais dessus mdr"
L36_1.m_SubTitle_FRA = L37_1
