L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_fTitleTalkTime = 0
L48_1 = "<color=#ffd34c>■■■■</color> 삼등 시민 주제에 뭔 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n<color=#ffd34c>■■ ■</color> 도전자 이겨라!!!!! 이겨서 리그의 새 역사를 써버려!!!!\n<color=#ffd34c>■ ■</color> 카나리아가 지금껏 잘 해오긴 했지만……\n<color=#ffd34c>■ ■</color> 냉정하게 S급인 카운터를 상대로 어떻게 이길지 잘 모르겠다.\n<color=#ffd34c>■ ■</color> 아마도 이변은 없지 싶음.\n<color=#ffd34c>■■ ■</color> ㄴ222222222222222222\n<color=#ffd34c>■ ■■■</color> ㄴ33333333333333333333"
L47_1.m_SubTitle_KOREA = L48_1
L47_1.m_fSubTitleTalkTime = 0
L48_1 = "<color=#ffd34c>■■■■</color> と、3等市民が申していますｗｗｗｗｗ\n<color=#ffd34c>■■ ■</color> チャレンジャー、勝て！！！　勝ってリーグに新しい歴史を刻みこむんだ！！！\n<color=#ffd34c>■ ■</color> カナリアもここまで健闘したけど……\n<color=#ffd34c>■ ■</color> さすがにSランクカウンターが相手じゃ勝ち目があるかどうか。\n<color=#ffd34c>■ ■</color> たぶん順当な結果になるだろうな。\n<color=#ffd34c>■■ ■</color> ↑それなああ\n<color=#ffd34c>■ ■■■</color> ↑まじそれなああ"
L47_1.m_SubTitle_JPN = L48_1
L48_1 = "<color=#ffd34c>■■■■</color> As if a third-grade citizen can do that. HAHAHAHAHA!\n<color=#ffd34c>■■ ■</color> Let's win this!!!! We're gonna witness history!!!!\n<color=#ffd34c>■ ■</color> Canary Squad's had a good run so far, but...\n<color=#ffd34c>■ ■</color> Truthfully, I don't see how they can win against a grade S Counter.\n<color=#ffd34c>■ ■</color> I don't think there's gonna be an upset.\n<color=#ffd34c>■■ ■</color> Same.\n<color=#ffd34c>■ ■■■</color> Yup."
L47_1.m_SubTitle_ENG = L48_1
L48_1 = "<color=#ffd34c>■■■■</color> 不過就是三等市民，呵呵呵呵\n<color=#ffd34c>■■ ■</color> 挑戰者加油！！！！刷新聯賽紀錄！！！\n<color=#ffd34c>■ ■</color> 金絲雀表現是不錯……\n<color=#ffd34c>■ ■</color> 冷靜想想，人家可是S級制裁者，是要怎麼贏？\n<color=#ffd34c>■ ■</color> 應該大局已定吧？\n<color=#ffd34c>■■ ■</color> 喔喔喔喔喔\n<color=#ffd34c>■ ■■■</color> 呵呵呵呵呵呵"
L47_1.m_SubTitle_TWN = L48_1
L48_1 = "<color=#ffd34c>■■■■</color> ราวกับว่าพลเมืองเกรด3 สามารถทำเช่นนั้นได้ ฮ่าฮ่าฮ่าฮ่า!\n<color=#ffd34c>■■ ■</color> มาชนะกันเถอะ!!!! เราจะได้เห็นประวัติศาสตร์ !!!!\n<color=#ffd34c>■ ■</color> หน่วยแคนารีทำได้ดีมาก แต่...\n<color=#ffd34c>■ ■</color > จริงๆ แล้ว ฉันไม่เห็นว่าพวกเขาจะเอาชนะเคาน์เตอร์เกรด S ได้อย่างไร\n<color=#ffd34c>■ ■</color> ฉันไม่คิดว่าจะต้องเสียใจ\n<color=#ffd34c>■■ ■</color> เหมือนกัน\n<color=#ffd34c>■ ■■■</color> ใช่แล้ว"
L47_1.m_SubTitle_THA = L48_1
L48_1 = "<color=#ffd34c>■■■■</color> Nói cứ như một công dân hạng ba có thể làm được vậy. HAHAHAHAHA!\n<color=#ffd34c>■■ ■</color> Hãy giành chiến thắng nào!!!! Chúng ta sẽ chứng kiến lịch sử!!!!\n<color=#ffd34c>■ ■</color> Cho đến nay, Tiểu đội Canary đã thi đấu rất tốt, nhưng...\n<color=#ffd34c>■ ■</color> Thành thật mà nói, tôi không hiểu làm thế nào họ sẽ thắng được một Counter cấp S.\n<color=#ffd34c>■■</color> Tôi không nghĩ sẽ có chuyện khó chịu.\n<color=#ffd34c>■ ■</color> Tôi cũng thế.\n<color=#ffd34c>■ ■■■</color> Yup."
L47_1.m_SubTitle_VTN = L48_1
L48_1 = "<color=#ffd34c>■■■■</color>区区三等市民，竟敢口出狂言，噗哈哈哈哈哈\n<color=#ffd34c>■■ ■</color>挑战者必胜！！！夺下冠军，写下联赛的新历史！！！！！\n<color=#ffd34c>■ ■</color>虽说金丝雀的表现一直很好……\n<color=#ffd34c>■ ■</color>冷静来说，我不知道他们准备怎么打赢S级制裁者。\n<color=#ffd34c>■ ■</color>恐怕是没有意外了。\n<color=#ffd34c>■■ ■</color> ㄴ同意\n<color=#ffd34c>■ ■■■</color> ㄴ1111111111"
L47_1.m_SubTitle_SCN = L48_1
L48_1 = "<color=#ffd34c>■■■■</color> Als ob Bürger dritter Klasse den Champion bezwingen könnten! LOL!\n<color=#ffd34c>■■ ■</color> Ihr könnt es schaffen, Herausforderer!!!!! Schnappt euch den Sieg und schreibt Geschichte in der Liga!!!!\n<color=#ffd34c>■ ■</color> Der Canary Trupp hat sich bis jetzt echt gut geschlagen ...\n<color=#ffd34c>■ ■</color> Ich frage mich echt, wie sie gegen einen Klasse-S-Counter gewinnen wollen.\n<color=#ffd34c>■ ■</color> Ich denke, dass es wahrscheinlich keine größeren Überraschungen geben wird.\n<color=#ffd34c>■■ ■</color> 222222222222222222\n<color=#ffd34c>■ ■■■</color> 33333333333333333333"
L47_1.m_SubTitle_DEU = L48_1
L48_1 = "<color=#ffd34c>■■■■</color> Pour qui elle se prend cette citoyenne de troisième zone mdrrr\n<color=#ffd34c>■■ ■</color> Je suis avec toi ! Gagne et écris une nouvelle page de l'histoire de la Compétition !!\n<color=#ffd34c>■ ■</color> Les canaris se sont bien débrouillés jusqu'à maintenant mais...\n<color=#ffd34c>■ ■</color> Je vois pas comment ils peuvent gagner contre un Counter de grade S\n<color=#ffd34c>■ ■</color> Je crois que le match est écrit d'avance\n<color=#ffd34c>■■ ■</color> ++++\n<color=#ffd34c>■ ■■■</color> +++++++"
L47_1.m_SubTitle_FRA = L48_1
