L3_1.m_Talk_SCN = L4_1
L4_1 = "Das angreifende Team gewinnt, wenn es die Basis des Gegners innerhalb des Zeitlimits erobert oder alle Gegner besiegt!"
L3_1.m_Talk_DEU = L4_1
