L6_1.m_Talk_TWN = L7_1
L7_1 = "และเพื่อการอ้างอิงเท่านั้น อัตราการโจมตี-ป้องกันของแชมป์เปี้ยนไร้พ่ายของเราคือ 3 ต่อ 7!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Và chỉ để tham khảo, tỷ lệ tấn công-phòng thủ của nhà vô địch bất bại của chúng ta là 3 trên 7!"
L6_1.m_Talk_VTN = L7_1
