L9_1 = "앗! 말씀드리는 순간 던져지는 운명의 동전─!!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "あっ！　そう言っているうちに、今、運命のコインが投げられた─！！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Oh! And in this very moment! The coin of fate has been tossed!!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "喔！話才剛說完，立刻就擲出命運的硬幣—！！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "โอ้! และ ณ วินาทีนี้เอง! เหรียญแห่งโชคชะตาถูกโยนทิ้งแล้ว!!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ồ! Và ngay trong thời điểm này! Đồng xu định mệnh đã được tung lên!!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "啊！话音刚落，决定命运的硬币掷向了空中——！！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Oh! Und der langersehnte Moment ist gekommen! Die Münze des Schicksals wurde geworfen ─!!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oh ! La pièce du tirage au sort vient juste d'être lancée !"
L8_1.m_Talk_FRA = L9_1
