L15_1.m_Face = "UNIT_PRIDE"
L15_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "이거 아무래도 행운의 여신마저 내 편을 들어주는 것 같은데?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "どうやら幸運の女神ですら、私の味方みたいよ？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It seems that even lady luck is on my side."
L15_1.m_Talk_ENG = L16_1
L16_1 = "幸運女神似乎是站在我這邊的呢？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ดูเหมือนว่าแม้แต่โชคของผู้หญิงก็ยังเข้าข้างฉัน"
L15_1.m_Talk_THA = L16_1
L16_1 = "Có vẻ như ngay cả Nữ Thần May Mắn cũng đứng về phía tôi."
L15_1.m_Talk_VTN = L16_1
L16_1 = "好像连幸运女神都站在我这边呢？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Es scheint, als wäre sogar die Glücksgöttin auf meiner Seite."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Il semble que même la déesse de la chance soit de mon côté."
L15_1.m_Talk_FRA = L16_1
