L20_1 = "CHARADE2_ACT4_STAGE1_START@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 5700403
L19_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_PRIDE"
L19_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L20_1 = "L"
L19_1.m_Pos = L20_1
L20_1 = "어때, 루이즈? 네가 원한다면 공격을 선택해줄 수도 있는데?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "どう、ルイーズ？　あなたが望むなら攻撃を選んであげてもいいわよ？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Anything you'd like to say, Louisé? I could choose to attack if that's what you want."
L19_1.m_Talk_ENG = L20_1
L20_1 = "怎麼樣，露易絲？你想要的話，我可以選擇當進攻方。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "คุณอยากจะพูดอะไร หลุยส์? ฉันสามารถเลือกโจมตีได้ถ้านั่นคือสิ่งที่คุณต้องการ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Có muốn nói gì không, Louisé? Tôi có thể chọn tấn công nếu nhóc muốn."
L19_1.m_Talk_VTN = L20_1
L20_1 = "怎么样，路易斯？如果你愿意，我可以让你选择防御。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Was wäre dir lieber, Louise? Ich könnte mich für einen Angriff entscheiden, wenn du das willst."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Quelque chose à dire, Louise ? Je pourrais toujours choisir d'attaquer si tu préfères !"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "CHARADE2_ACT4_STAGE1_START@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5700403
L20_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_SERIOUS"
L20_1.m_Face = L21_1
L21_1 = "FELICETTE_CANARY_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "R"
L20_1.m_Pos = L21_1
L21_1 = "공격이든 방어든 상관없어요. 어차피 전멸시켜서 이길 거니까."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "攻撃でも防御でも構いません。どのみち全滅させて勝ちますから。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Attack, defend. It doesn't matter. We're going to win by retiring every member in your team."
L20_1.m_Talk_ENG = L21_1
L21_1 = "攻或守我都無所謂，反正我會讓你們全軍覆沒。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "โจมตีปกป้อง มันไม่สำคัญ เราจะเป็นผู้ชนะโดยการออกจากสมาชิกทุกคนในทีมของคุณ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tấn công, phòng thủ. Đều không quan trọng. Chúng tôi sẽ giành chiến thắng bằng cách cho mọi thành viên trong nhóm cô về hưu."
L20_1.m_Talk_VTN = L21_1
L21_1 = "无论是攻击还是防守，都无所谓。反正我会让你们全军覆没。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ob Sie nun angreifen oder verteidigen, spielt keine Rolle. Wir werden gewinnen, indem wir jedes Mitglied in Ihrem Team außer Gefecht setzen werden."
L20_1.m_Talk_DEU = L21_1
L21_1 = "L'attaque ou la défense, ça n'a pas d'importance. Nous allons gagner en éliminant tous les membres de votre équipe."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "CHARADE2_ACT4_STAGE1_START@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5700403
L21_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
