L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L22_1 = "L"
L21_1.m_Pos = L22_1
L21_1.m_Crash = 10
L22_1 = "후후, 좋은 각오야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ふふ、いい覚悟ね。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Fu fuu, I like how determined you are."
L21_1.m_Talk_ENG = L22_1
L22_1 = "呵呵，勇氣可嘉。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฟู ฟู ฉันชอบที่คุณมีความมุ่งมั่น"
L21_1.m_Talk_THA = L22_1
L22_1 = "Fu fuu, tôi thích sự quyết tâm đó."
L21_1.m_Talk_VTN = L22_1
L22_1 = "呵呵，决心可嘉。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Hoho, ich mag es, wie entschlossen du bist."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hu hu, j'aime te voir aussi déterminée."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "CHARADE2_ACT4_STAGE1_START@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5700403
L22_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L23_1 = "L"
L22_1.m_Pos = L23_1
L23_1 = "그럼, 기대할게. 정상에서 기다리고 있을 테니까."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "じゃあ、期待しておくわね。頂上で待っているわ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Then, I'll be waiting for you at the top."
L22_1.m_Talk_ENG = L23_1
L23_1 = "那我就期待一下吧，我會在上面等你。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แล้วฉันจะรอคุณอยู่ที่ด้านบน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Vậy thì tôi sẽ đợi nhóc ở phía trên."
L22_1.m_Talk_VTN = L23_1
L23_1 = "那我期待一下吧，我会在顶峰等着你。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Na dann, ich freue mich auf unser Spiel. Ich werde oben auf dich warten."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Dans ce cas, je te retrouverai au sommet."
L22_1.m_Talk_FRA = L23_1
