L42_1 = "파이팅!! 저희를 꺾고 올라갔으니까, 당당하게 이기라고요─!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ファイト！！　我々に勝ったんですから、自信を持って勝ちに行ってください！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Go, Canary Squad! You made it there by defeating us! So beat her fair and square!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "加油！！你們是打敗我們進到決賽的，一定光明正大地贏—！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไปซะ หน่วยแคนารี! คุณเอาชนะพวกเราได้! ดังนั้นเอาชนะความยุติธรรมของเธอให้ได้!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tiến lên, đội Canary! Các cô đã đánh bại chúng tôi và làm được! Hãy đánh bại cô ta công bằng và thẳng thắn!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "加油！！要带着我们的那份，堂堂正正地赢啊——！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Auf geht’s, Canary Trupp! Ihr habt es bis ins Finale geschafft, weil ihr uns besiegt habt! Also macht sie fertig!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Allez, l'escouade Canari ! Vous vous êtes battus pour arriver jusqu'ici alors continuez jusqu'au bout !"
L41_1.m_Talk_FRA = L42_1
