L17_1 = "반대로 공격 측은 제한 시간 안에 수단과 방법을 가리지 않고 옥상을 점령하면 승리라구!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "逆に、攻撃チームは制限時間内にどんな手を使ってでも屋上を占領すれば勝ち！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "However, the attacking team will win if they take over the rooftop within the time limit, using any force necessary!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "而進攻方只要在限制時間內，想盡辦法佔領頂樓，就能高唱凱歌！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "อย่างไรก็ตาม ทีมโจมตีจะเป็นผู้ชนะหากยึดครองดาดฟ้าได้ภายในเวลาที่กำหนด โดยใช้กำลังเท่าที่จำเป็น!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tuy nhiên, đội tấn công sẽ giành chiến thắng nếu chiếm được sân thượng trong thời gian giới hạn bằng bất kỳ sức mạnh nào cần thiết!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "相反，攻击方要在限制时间内，不择手段地占领楼顶就能获胜！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das angreifende Team wird jedoch gewinnen, wenn es innerhalb des Zeitlimits mit allen erforderlichen Mitteln das Dach erobert!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Cependant, l'équipe attaquante l'emportera si elle parvient à reprendre le toit dans le délai imparti, en utilisant tous les moyens nécessaires !"
L16_1.m_Talk_FRA = L17_1
