L20_1 = "CHARADE2_ACT4_STAGE1_START@119#SubTitle"
L19_1.m_CutScenKey_SubTitle = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 5700403
L19_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_fTitleTalkTime = 0
L20_1 = "<color=#ffd34c>■■■</color> 가능하다면, 본선 1경기처럼 곧장 직진하는 게 베스트겠지.\n<color=#ffd34c>■ ■■</color> 챔피언이 호구임? 뽀뽀하러 오는 걸 보고만 있게?\n<color=#ffd34c>■ ■■</color> 복잡해도 지하루트로 돌파하는 게 당연하잖아.\n<color=#ffd34c>■■■</color> ㅉㅉ 너 샤레이드 출신 아니지?\n<color=#ffd34c>■■■</color> 사채업자 사건 때문에 도시 보안 레벨이 얼마나 올라갔는데.\n<color=#ffd34c>■■■</color> 지하 루트 쪽은 방어 측이 압도적으로 유리하다고."
L19_1.m_SubTitle_KOREA = L20_1
L19_1.m_fSubTitleTalkTime = 0
L20_1 = "<color=#ffd34c>■■■</color> 可能であれば、本戦1試合目みたいに、まっすぐ突破するのがベストだろうな。\n<color=#ffd34c>■ ■■</color> チャンピオンはバカじゃないだろ？　まっすぐ来るのに対して何もせずに見ていると思うか？\n<color=#ffd34c>■ ■■</color> 多少複雑でも地下ルートで行くべきだろうな。\n<color=#ffd34c>■■■</color> 何言ってんだ。お前シャレードを知らないだろ。\n<color=#ffd34c>■■■</color> 闇金業者事件以来、都市のセキュリティがめっちゃ厳しくなってんだぞ。\n<color=#ffd34c>■■■</color> 地下ルートは防御側が圧倒的に有利だって。"
L19_1.m_SubTitle_JPN = L20_1
L20_1 = "<color=#ffd34c>■■■</color> If possible, the best would be going straight for the goal like they did in their first match.\n<color=#ffd34c>■ ■■</color> The champion's not dumb. You think she'll just let them ram a kiss at her?\n<color=#ffd34c>■ ■■</color> Of course the best route is to go underground, even if it's a maze down there.\n<color=#ffd34c>■■■</color> SMH. You're not from Charade, are you?\n<color=#ffd34c>■■■</color> Do you know how much they increased the security around here after that loan shark incident?\n<color=#ffd34c>■■■</color> The underground route is way easier to defend."
L19_1.m_SubTitle_ENG = L20_1
L20_1 = "<color=#ffd34c>■■■</color> 可以的話，像決賽第一場比賽一樣，直接進攻是最好的吧？\n<color=#ffd34c>■ ■■</color> 當冠軍是塑膠？會看著你們進攻不管？\n<color=#ffd34c>■ ■■</color> 雖然有點複雜，但應該是要突破地下路線吧？\n<color=#ffd34c>■■■</color> 你不是查雷德的人吧？\n<color=#ffd34c>■■■</color> 高利貸事件後，城市安全層級提高很多欸。\n<color=#ffd34c>■■■</color> 地下路線的話防守方有絕對優勢。"
L19_1.m_SubTitle_TWN = L20_1
L20_1 = "<color=#ffd34c>■■■</color> ถ้าเป็นไปได้ สิ่งที่ดีที่สุดคือการมุ่งตรงไปสู่เป้าหมายเหมือนกับที่พวกเขาทำในนัดแรก\n<color=#ffd34c>■ ■■</color> แชมป์เปี้ยน ไม่โง่ คุณคิดว่าเธอจะปล่อยให้พวกเขาจูบเธอเหรอ?\n<color=#ffd34c>■ ■■</color> แน่นอนว่าเส้นทางที่ดีที่สุดคือลงไปใต้ดิน แม้ว่าด้านล่างจะเป็นเขาวงกตก็ตาม\n<color=#ffd34c>■■■</color>  ไม่เอา คุณไม่ได้มาจากชาเรดใช่ไหม\n<color=#ffd34c>■■■</color> คุณรู้ไหมว่าพวกเขาเพิ่มความปลอดภัยแถวนี้มากแค่ไหนหลังจากเหตุการณ์เจ้าหนี้เงินกู้\n<color=#ffd34c>■■■</color> เส้นทางใต้ดินนั้นป้องกันได้ง่ายกว่ามาก"
L19_1.m_SubTitle_THA = L20_1
L20_1 = "<color=#ffd34c>■■■</color> Nếu có thể, tốt nhất là họ sẽ thẳng tiến về phía mục tiêu giống như họ đã làm trong trận đấu đầu tiên.\n<color=#ffd34c>■ ■■</color> Nhà vô địch không ngu đâu. Bạn nghĩ cô ấy sẽ để họ hôn mình à?\n<color=#ffd34c>■ ■■</color> Tất nhiên cách tốt nhất là đi xuống lòng đất, ngay cả khi dưới đó là mê cung.\n<color=#ffd34c>■■■</color> Ông không ở Charade, phải không?\n<color=#ffd34c>■■■</color> Có biết họ đã tăng cường an ninh quanh đây đến mức nào sau vụ cho vay nặng lãi không?\n<color=#ffd34c> ■■■</color> Tuyến đường ngầm dễ phòng thủ hơn nhiều."
L19_1.m_SubTitle_VTN = L20_1
L20_1 = "<color=#ffd34c>■■■</color>如果可以的话，最好的就是像第一场比赛那样直接进攻。\n<color=#ffd34c>■ ■■</color>你当冠军是傻子啊？看到进攻还会纹丝不动？\n<color=#ffd34c>■ ■■</color>虽然复杂一点，但当然是要通过地下路线突破了。\n<color=#ffd34c>■■■</color>啧啧，你不是查雷德出身吧？\n<color=#ffd34c>■■■</color>因为高利贷那件事，城市安保等级不知道提高了多少呢。\n<color=#ffd34c>■■■</color>地下路线还是对防御方更加有利。"
L19_1.m_SubTitle_SCN = L20_1
L20_1 = "<color=#ffd34c>■■■</color> Wenn möglich, wäre es am besten, sie so wie beim ersten Spiel der Hauptrunde frontal anzugreifen.\n<color=#ffd34c>■ ■■</color> Der Champion ist doch nicht dumm. Sie wird den Kuss abfangen, bevor sie ihr überhaupt zu nahe kommen können.\n<color=#ffd34c>■ ■■</color> Auch wenn es kompliziert ist, wäre der unterirdische Pfad natürlich am besten für einen Durchbruch geeignet.\n<color=#ffd34c>■■■</color> Pff. Du kommst nicht aus Charade, oder?\n<color=#ffd34c>■■■</color> Weißt du überhaupt, wie sehr die Stadt die Sicherheitsmaßnahmen wegen dieses Kredithai-Vorfalls erhöht hat?\n<color=#ffd34c>■■■</color> Der unterirdische Pfad bietet dem verteidigenden Team einen überwältigenden Vorteil."
L19_1.m_SubTitle_DEU = L20_1
L20_1 = "<color=#ffd34c>■■■</color> Je crois qu'ils feraient mieux de foncer tout droit, comme pour leur 1er match\n<color=#ffd34c>■ ■■</color> Tu crois que la championne va rester sans rien faire ?\n<color=#ffd34c>■ ■■</color> Même si c'est compliqué, ils devraient passer par la voie souterraine\n<color=#ffd34c>■■■</color> Tss t'es pas de Charade toi, si ?\n<color=#ffd34c>■■■</color> Le niveau de sécurité de la ville a vachement augmenté depuis l'incident de la prêteuse sur gage\n<color=#ffd34c>■■■</color> En prenant la voie souterraine, la défense a un avantage nettement supérieur"
L19_1.m_SubTitle_FRA = L20_1
L20_1 = {}
