L25_1 = "CHARADE2_ACT4_STAGE1_START@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5700403
L24_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "FELICETTE_CANARY_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "……일단 사전에 이야기한대로 지하 루트를 먼저 공략해주세요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "……とりあえず事前にお話した通り、まずは地下ルートを攻略してください。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "...Let's first try the underground route like we planned."
L24_1.m_Talk_ENG = L25_1
L25_1 = "……就照事先計畫好的，先拿下地下路線吧。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "...ลองใช้เส้นทางใต้ดินตามที่วางแผนไว้กันก่อน"
L24_1.m_Talk_THA = L25_1
L25_1 = "…Đầu tiên hãy thử đi con đường ngầm như chúng ta đã lên kế hoạch."
L24_1.m_Talk_VTN = L25_1
L25_1 = "……按事先说好的，先攻略地下路线吧。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "... Lasst uns zuerst den unterirdischen Pfad ausprobieren, so wie wir es geplant haben."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tentons de passer par la voie souterraine, comme prévu."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "CHARADE2_ACT4_STAGE1_START@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5700403
L25_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "FELICETTE_CANARY_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "모든 걸 예측할 수는 없어요. 다음 수는 상대의 대처를 보면서 그때그때 변경할 거예요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "すべてを予測することはできません。次の手は相手の出方次第で決めます。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "We can't predict everything that happens, so let's improvise after seeing how the opponent reacts."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我們無法預測到所有東西，所以下一步要根據對方的行動再隨機應變。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เราไม่สามารถคาดเดาทุกสิ่งที่เกิดขึ้นได้ ดังนั้นมาด้นสดหลังจากเห็นว่าคู่ต่อสู้มีปฏิกิริยาอย่างไร"
L25_1.m_Talk_THA = L26_1
L26_1 = "Chúng ta không thể đoán trước được mọi chuyện nên hãy ứng biến sau khi xem phản ứng của đối phương."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我们无法预测到所有的东西。所以下一步要看对方的动向如何，然后视情况更改计划。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wir können nicht alles vorhersehen, also improvisieren wir, nachdem wir gesehen haben, wie unser Gegner reagiert."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Nous ne pouvons pas prédire tout ce qui va se passer, alors improvisons après avoir vu comment l'adversaire réagit."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
