L28_1 = "UNIT_DESPAIR"
L27_1.m_Face = L28_1
L28_1 = "STAFF_CANARY_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "정말 이래도 괜찮을까? 상대 분위기가 심상치 않아."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "本当にこれでいいのかな？　相手の雰囲気が普通じゃないよ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Are you sure about this? Our opponent looks super tough."
L27_1.m_Talk_ENG = L28_1
L28_1 = "這樣真的沒問題嗎？對方的氣氛感覺不太對勁。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "คุณแน่ใจเกี่ยวกับเรื่องนี้หรือไม่? คู่ต่อสู้ของเราดูแข็งแกร่งมาก"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chắc chứ? Đối thủ của chúng ta có vẻ siêu khó."
L27_1.m_Talk_VTN = L28_1
L28_1 = "真的没问题吗？对方的氛围很不寻常……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Bist du sicher, dass das klappt? Unser Gegner ist ziemlich stark."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Tu es sûre de toi ? Notre adversaire a vraiment l'air coriace."
L27_1.m_Talk_FRA = L28_1
