L29_1 = "STAFF_CANARY_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "챔피언이 새로 기용한 맴버들…… 라이카를 공격했던 녀석들 맞지?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "チャンピオンが起用した新しいメンバーたち……ライカを攻撃してきた奴らだよね？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "The new members the champion hired... aren't they the ones that attacked Laika?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "冠軍新任用的選手……是攻擊萊卡的那些人吧？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "สมาชิกใหม่ที่แชมป์เปี้ยนจ้างมา... พวกเขาคือคนที่โจมตีไลกาไม่ใช่เหรอ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Những thành viên mới mà nhà vô địch thuê... chẳng phải chúng đã tấn công Laika sao?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "冠军新引进的队友……是攻击了莱卡的那些家伙吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Die neuen Mitglieder, die der Champion angeheuert hat ... sind das nicht die Typen, die Leica angegriffen haben?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Les nouveaux membres que la championne a recrutés... on dirait ceux qui ont attaqué Leica, non ?"
L28_1.m_Talk_FRA = L29_1
