L31_1.m_Talk_THA = L32_1
L32_1 = "*Thở dài* Phải ngưỡng mộ sự kiên trì của chúng."
L31_1.m_Talk_VTN = L32_1
L32_1 = "哈啊，那些家伙还真是执着啊。"
