L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5700403
L32_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
