L32_1.m_Face = "UNIT_IDLE"
L33_1 = "LAIKA_CANARY_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "L"
L32_1.m_Pos = L33_1
L33_1 = "그래도 당장 경기 중에는 괜찮을 거야. 녀석들이 원하는 건 내 머릿속 정보니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "でも試合中は大丈夫だと思うよ。奴らが求めているのは私の頭の中の情報だから。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I'll be okay during the match. Because what they want is the information inside my head."
L32_1.m_Talk_ENG = L33_1
L33_1 = "但比賽途中應該沒什麼問題，他們想要的是我腦子裡的情報而已。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันจะไม่เป็นไรในระหว่างการแข่งขัน เพราะสิ่งที่พวกเขาต้องการคือข้อมูลในหัวของฉัน"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi sẽ ổn trong suốt trận thôi. Bởi vì thứ chúng muốn là thông tin trong đầu tôi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "比赛途中我会没事的，他们想要的是我脑子里的情报而已。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich werde trotzdem während des Spiels zurechtkommen. Denn was diese Typen wollen, sind die Informationen in meinem Kopf."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je n'ai rien à craindre pendant ce match. Parce que ce qu'ils veulent, ce sont les informations dans ma tête."
L32_1.m_Talk_FRA = L33_1
