L36_1 = "FELICETTE_CANARY_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "경기 중에 누군가를 죽이면, 그 즉시 경기는 패배 처리되고 당사자는 실격 처리돼요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "試合中に誰かを殺せば、その瞬間試合は敗北となり、当事者は失格になります。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Killing someone during the match will automatically disqualify them."
L35_1.m_Talk_ENG = L36_1
L36_1 = "要是在比賽中殺了人，不只會立刻輸掉比賽，當事人也會立刻遭到淘汰。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "การฆ่าใครสักคนระหว่างการแข่งขันจะทำให้พวกเขาถูกตัดสิทธิ์โดยอัตโนมัติ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Giết người trong trận đấu sẽ bị xử thua."
L35_1.m_Talk_VTN = L36_1
L36_1 = "而且比赛中如果有人死了，那么就会立即被判为战败，并且当事者将被取消资格。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wenn jemand während des Spiels getötet wird, wird er automatisch disqualifiziert."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tuer quelqu'un pendant le match les disqualifieront automatiquement."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "CHARADE2_ACT4_STAGE1_START@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5700403
L36_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "FELICETTE_CANARY_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "자기 타이틀을 위해서라도 오지만디아스가 이 경기에서 살인을 용납할 리 없어요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "自分のタイトルを守るためにも、オジマンディアスがこの試合で殺人を許すはずがありません。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Ozymandias won't tolerate any killing in the match since her title as champion is on the line."
L36_1.m_Talk_ENG = L37_1
L37_1 = "為了維護她的頭銜，奧茲曼迪亞斯不會允許在比賽中殺人的。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "โอซีแมนเดียสจะไม่ยอมให้มีการสังหารใดๆ ในการแข่งขัน เนื่องจากตำแหน่งแชมป์เปี้ยนของเธออยู่บนเส้นตาย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ozymandias sẽ không tha thứ cho bất kỳ hành vi giết người nào trong trận vì danh hiệu vô địch của cô ta đang bị đe dọa."
L36_1.m_Talk_VTN = L37_1
L37_1 = "为了自己的头衔，奥兹曼迪亚斯也不会容忍在这个比赛中出现杀人的。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ozymandias würde in diesem Spiel auf keinen Fall einen Mord zulassen, da ihr Titel als Champion auf dem Spiel steht."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ozymandias ne tolérera aucun meurtre pendant ce match puisque son titre de championne est en jeu."
L36_1.m_Talk_FRA = L37_1
