L40_1 = "ROI_PRYDWEN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "L"
L39_1.m_Pos = L40_1
L40_1 = "잠깐, 꼬마 대장. 그쪽 카운터는 노엘뿐이잖아."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "待て、チビ隊長。そっちのカウンターはノエルだけだろ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Wait, Little Captain. Isn't Noelle the only Counter you have?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "等等，小不點隊長，你這邊的制裁者只有洛艾兒吧？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "รอก่อนนะกัปตันน้อยโนเอลเป็นเพียงเคาน์เตอร์เดียวที่คุณมีไม่ใช่หรือ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đợi đã, Đội trưởng nhí. Noelle không phải là Counter duy nhất sao?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "等等，小不点队长。你那边的制裁者只有诺艾尔吧。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Warte mal, kleine Kommandantin. Ist Noelle nicht der einzige Counter, den wir haben?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Une minute, petite capitaine. Noelle est le seul Counter qu'on a dans l'équipe, non ?"
L39_1.m_Talk_FRA = L40_1
