L40_1.m_CharStrID = L41_1
L41_1 = "L"
L40_1.m_Pos = L41_1
L41_1 = "경우에 따라 전력을 나누게 될지도 모르는데 괜찮겠어?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "場合によっては戦力を分散させることもあると思うが、大丈夫なのか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We might end up having to split our team. Are you okay with that?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "說不定要根據情況分配戰力，這樣真的沒關係嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เราอาจจะต้องแยกทีมออกจากกัน คุณโอเคกับเรื่องนั้นไหม?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cuối cùng chúng ta có thể phải chia nhóm. Thế ổn chứ?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "我们大概是要分开行动了，你们那边没关系吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wir müssen möglicherweise unser Team aufteilen. Wärst du damit einverstanden?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "On aura peut-être besoin de diviser notre équipe le moment venu."
L40_1.m_Talk_FRA = L41_1
