L43_1 = "I'm not sure, but considering how Ozymandias likes to play out her matches..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我也不太確定，但根據奧茲曼迪亞斯的作戰習慣……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันไม่แน่ใจ แต่เมื่อพิจารณาว่าโอซีแมนเดียสชอบเล่นแมตช์ของเธออย่างไร..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi không chắc, nhưng xét đến cách Ozymandias thích chơi đùa với các trận đấu của mình..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "虽然不能断言，但考虑到奥兹曼迪亚斯的作战习惯……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich bin mir nicht sicher, aber wenn man bedenkt, wie Ozymandias ihre Spiele gerne austrägt ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je ne suis pas sûre, mais compte tenu de la façon dont Ozymandias aime jouer ses matchs..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "CHARADE2_ACT4_STAGE1_START@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5700403
L43_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "FELICETTE_CANARY_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "저희가 대담하게 나가면 나갈수록, 오히려 승부에 응해줄 가능성이 크다고 생각해요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "私たちが大胆に出れば出るほど、むしろ応戦してくる可能性が高いと思います。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "The bolder we come at her, the higher our chances are of her responding to a showdown."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我們的行動越是大膽，她反而越有可能跟我們正面交鋒。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ยิ่งเราเข้าใกล้เธอมากเท่าไร โอกาสที่เธอจะตอบสนองต่อการเผชิญหน้าก็จะยิ่งมากขึ้นเท่านั้น"
L43_1.m_Talk_THA = L44_1
L44_1 = "Chúng ta càng tiếp cận cô ta táo bạo thì khả năng cô ấy phản ứng trước một cuộc thách đấu càng cao."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我们越是大胆，她反而就越可能答应我们的对决请求。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich denke, je mutiger wir voranschreiten, desto wahrscheinlicher ist es, dass sie mit einem finalen Kräftemessen reagiert."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Plus nous avançons vers elle avec détermination et plus elle risque de riposter."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "CHARADE2_ACT4_STAGE1_START@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 5700403
L44_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
