L45_1 = "UNIT_SERIOUS"
L44_1.m_Face = L45_1
L45_1 = "FELICETTE_CANARY_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L44_1.m_Crash = 10
L45_1 = "……그리고 단 한 번."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "……そして1度きりですが。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "...And just once."
L44_1.m_Talk_ENG = L45_1
L45_1 = "……然後只有一次機會……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "...และเพียงครั้งเดียว"
L44_1.m_Talk_THA = L45_1
L45_1 = "...Và chỉ một lần thôi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "……然后，只有一次……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "... Und nur einmal."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Sans oublier..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "CHARADE2_ACT4_STAGE1_START@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5700403
L45_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "FELICETTE_CANARY_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "저에겐 승부를 결정지을 수 있는 비장의 수단이 있어요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "私には勝負を決定づけられる切り札があります。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I have an ace up my sleeve that can end the match."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我有可以一次定勝負的絕招。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉันมีไพ่เอซที่สามารถจบการแข่งขันได้"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi có một con át chủ bài có thể kết thúc trận đấu."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我有可以决定胜负的杀手锏。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich habe ein Ass im Ärmel, das das Spiel beenden kann."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Que j'ai un atout dans ma manche qui pourrait mettre fin au match."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "CHARADE2_ACT4_STAGE1_START@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5700403
L46_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
