L47_1 = "FELICETTE_CANARY_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "그걸로 오지만디아스를 쓰러트릴 거예요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "それでオジマンディアスを倒します。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "And I will defeat Ozymandias with it."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我要用那個打敗奧茲曼迪亞斯。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "และฉันจะเอาชนะ โอซีแมนเดียสด้วยมัน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Và tôi sẽ đánh bại Ozymandias bằng nó."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我要用那个打败奥兹曼迪亚斯。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Und ich werde Ozymandias damit besiegen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Et je compte bien vaincre Ozymandias avec."
L46_1.m_Talk_FRA = L47_1
