L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 5700403
L49_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_PRIDE"
L50_1 = "ROI_PRYDWEN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "L"
L49_1.m_Pos = L50_1
L49_1.m_Crash = 10
L50_1 = "뭐야. 그런 게 있었으면, 진작 말을 하지 그랬냐."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "なんだ。そんなのがあるんだったら、早く言ってくれよ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Huh? Why didn't you say something before if you had something like that?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "什麼嘛？有絕招怎麼不早說。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฮะ? ทำไมคุณไม่พูดอะไรมาก่อนถ้าคุณมีอะไรแบบนั้น?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Huh? Tại sao nhóc không nói điều gì đó trước nếu có thứ gì đó như vậy?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "什么啊，既然有那种东西，那你怎么不早说。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Was?! Warum hast du nicht schon früher gesagt, dass du so etwas hast?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Hein ? Mais pourquoi tu l'as pas dit avant ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "CHARADE2_ACT4_STAGE1_START@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5700403
L50_1.m_CutScenStrID = "CHARADE2_ACT4_STAGE1_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "CHOWON_PERSONA_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "R"
L50_1.m_Pos = L51_1
L51_1 = "그럼 이번 작전의 최우선 전략 목표는 당신을 챔피언에게 접근시키는 것이로군요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "では今回の作戦の戦略的最優先目標はあなたをチャンピオンに接近させることですね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Then, our main objective will be to get you closer to the champion."
L50_1.m_Talk_ENG = L51_1
L51_1 = "那這次作戰的首要戰略目標，就是讓你接近冠軍。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "จากนั้น วัตถุประสงค์หลักของเราคือการทำให้คุณเข้าใกล้แชมป์เปี้ยนมากขึ้น"
L50_1.m_Talk_THA = L51_1
L51_1 = "Thế thì mục tiêu chính của chúng ta sẽ là đưa nhóc đến gần hơn với nhà vô địch."
L50_1.m_Talk_VTN = L51_1
L51_1 = "那这次作战的首要战略目标，就是让你接近冠军。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Das primäre strategische Ziel dieser Operation besteht also darin, dich so weit wie möglich zum Champion zu bringen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Dans ce cas, notre objectif principal est de vous permettre de vous rapprocher de la championne."
L50_1.m_Talk_FRA = L51_1
