L15_1 = "마침내 카나리아 스쿼드의 수송선이 날아오르면서 결승전이 시작됐다!!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "いよいよカナリア・スクワッドの輸送船が浮上して決勝戦が始まった！！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Canary Squad's transport aircraft has taken to the skies! The final game has officially begun!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "隨著金絲雀小隊的運輸機升空，宣布決賽正式開始！！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ยานขนส่งของหน่วยแคนารีขึ้นสู่ท้องฟ้าแล้ว! เกมสุดท้ายได้เริ่มต้นขึ้นอย่างเป็นทางการแล้ว!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Máy bay vận tải của Tiểu Đội Canary đã bay lên bầu trời! Trận đấu cuối cùng đã chính thức bắt đầu!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "金丝雀小队的运输机终于飞起来了，决赛正式开始！！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Das Transportflugzeug des Canary Trupps ist in die Lüfte emporgestiegen! Das letzte Spiel hat offiziell begonnen!!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "L'avion de transport de l'escouade Canari s'est envolé ! Le dernier match a officiellement commencé !"
L14_1.m_Talk_FRA = L15_1
