L17_1 = "으아아─!! 이젠 미치도 미치의 마음을 잘 모르겠어─!!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "うわぁ～！！　もうミッチーにも自分の気持ちがよくわからない～！！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Nuaagh–!! Now, I'm not even sure what this feeling is!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "哎呀呀—！！米琪也不知道到底要替誰加油才好啦—！！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "นัท-!! ตอนนี้ มิทซี่ ไม่แน่ใจด้วยซ้ำว่าเธอรู้สึกอย่างไร!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nuaagh–!! Bây giờ, Mitchie còn không chắc cảm giác này là gì nữa."
L16_1.m_Talk_VTN = L17_1
L17_1 = "呃啊啊——！！现在米琪米琪也不知道米琪是怎么想的——！！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Urgh ─!! Ich weiß jetzt auch nicht so recht, was ich von ihnen halten soll ─!!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ouaaargh !! Je n'arrive même plus à savoir quel sentiment m'habite !"
L16_1.m_Talk_FRA = L17_1
