L17_1.m_Crash = 15
L18_1 = "재수 없지만……!! 싹퉁머리도 없지만……!!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ムカつくけど……！！　礼儀知らずだけど……！！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I know they're pompous jerks...!! And really, really rude...!!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "雖然他們沒大沒小的……！！又沒禮貌……！！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ฉันรู้นะว่าพวกเขามันไอ้โง่...!! และหยาบคายมากจริงๆ...!!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi biết họ là những kẻ ngạo mạn...!! Và thực sự, rất thô lỗ...!!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "虽然很晦气……！！虽然没有礼貌……！！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich weiß, dass sie aufgeblasene Idioten sind ...!! Und wirklich rotzfrech, aber ...!!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Tout ce que je sais c'est qu'ils sont super agaçants...! Et vraiment grossiers...!"
L17_1.m_Talk_FRA = L18_1
