L18_1.m_CharScale = L19_1
L18_1.m_CharScaleTime = 0.01
L18_1.m_bCharPinup = true
L18_1.m_Crash = 30
L19_1 = "여기까지 왔으면, 설마? 하고 기대할 수밖에 없잖아! 그동안 너무 정이 들어버렸는걸─!!"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ここまで来たら、もしや？って期待するしかないじゃない！　もう情がたくさん移っちゃったよ～！！"
L18_1.m_Talk_JPN = L19_1
L19_1 = "But they made it this far, haven't they? So, how can I not root for them? I've gotten so attached to them now!!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "但事到如今，也只能期待他們的表現啦！這段時間對他們都產生感情咧—！！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่พวกเขามาไกลถึงขนาดนี้แล้วใช่ไหม? แล้วฉันจะไม่รูทพวกมันได้อย่างไร? ตอนนี้ฉันผูกพันกับพวกเขามาก!!"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nhưng họ đã đi xa đến mức này phải không? Vì vậy, sao tôi có thể không cổ vũ cho họ? Bây giờ tôi đã quá gắn bó với họ rồi!!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "但既然都来到这一步了，那就只能期待一下了！这段时间我都对他们有感情了呢——！！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Aber sie haben es bis hierhin geschafft! Wie kann ich sie also nicht anfeuern? Sie hängen mir mittlerweile echt am Herzen ─!!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Mais ils sont arrivés jusqu'ici, après tout. Alors, comment puis-je ne pas les soutenir ? Je suis trop attachée à eux maintenant !"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
