L19_1.m_bCharPinup = true
L20_1 = "그러니까 힘내! 카나리아 스쿼드─!!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "だから頑張ってね！！　カナリア・スクワッド─！！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "So, I'm rooting for you, Canary Squad!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "所以加油吧！金絲雀小隊—！"
L19_1.m_Talk_TWN = L20_1
